#ifndef AL_TESTS_SOURCE_GROUP_H
#define AL_TESTS_SOURCE_GROUP_H

#include <algorithm>
#include <cstddef>
#include <span>
#include <vector>

#include <AL/al.h>
#include <AL/efx.h>


namespace altest {

/* A named collection of AL source IDs.
 *
 * The group owns no AL sources itself: sources are generated by the caller
 * through alGenSources and attached/detached explicitly. Each source keeps an
 * independent state and can still be updated with the regular single-source
 * entry points at any time.
 */
class SourceGroup {
public:
    SourceGroup() = default;
    explicit SourceGroup(std::span<const ALuint> sources)
        : mSources{sources.begin(), sources.end()}
    { }

    /* Attaches a source to the group. Duplicate IDs are ignored so that the
     * same source can never be applied twice within one batch.
     */
    void addSource(ALuint source)
    {
        if(std::ranges::find(mSources, source) == mSources.end())
            mSources.push_back(source);
    }

    void addSources(std::span<const ALuint> sources)
    {
        for(ALuint source : sources)
            addSource(source);
    }

    /* Detaches a source. Detaching never deletes the underlying AL source.
     * Returns false if the ID was not part of the group.
     */
    bool removeSource(ALuint source)
    {
        auto iter = std::ranges::find(mSources, source);
        if(iter == mSources.end()) return false;
        mSources.erase(iter);
        return true;
    }

    void clear() noexcept { mSources.clear(); }

    [[nodiscard]] auto size() const noexcept -> std::size_t { return mSources.size(); }
    [[nodiscard]] auto empty() const noexcept -> bool { return mSources.empty(); }
    [[nodiscard]] auto sources() const noexcept -> std::span<const ALuint> { return mSources; }
    [[nodiscard]] auto contains(ALuint source) const noexcept -> bool
    { return std::ranges::find(mSources, source) != mSources.end(); }

    /* Returns true only when every member ID is a real source. This is a
     * pure query and raises no AL error; the setters themselves raise
     * AL_INVALID_NAME on a bad ID.
     */
    [[nodiscard]] auto validateSources() const -> bool
    {
        for(ALuint source : mSources)
        {
            if(alIsSource(source) == AL_FALSE)
            {
                /* alIsSource does not raise an error itself; the regular
                 * setters raise AL_INVALID_NAME on lookup failure.
                 */
                return false;
            }
        }
        return true;
    }

    /* Applies AL_GAIN to every member, equivalent to an alSourcef call per
     * source. Returns the number of members processed.
     */
    auto setGain(ALfloat gain) const -> std::size_t
    {
        for(ALuint source : mSources)
            alSourcef(source, AL_GAIN, gain);
        return mSources.size();
    }

    /* Applies a direct low-pass filter (AL_DIRECT_FILTER) to every member.
     * Pass 0 to clear the filter. Returns the number of members processed.
     */
    auto setDirectFilter(ALuint filter) const -> std::size_t
    {
        for(ALuint source : mSources)
            alSourcei(source, AL_DIRECT_FILTER, static_cast<ALint>(filter));
        return mSources.size();
    }

    /* Applies AL_DISTANCE_MODEL to every member. Returns the number of members
     * processed.
     */
    auto setDistanceModel(ALenum model) const -> std::size_t
    {
        for(ALuint source : mSources)
            alSourcei(source, AL_DISTANCE_MODEL, static_cast<ALint>(model));
        return mSources.size();
    }

    /* Combined batch update: gain, direct filter and distance model are
     * applied in the same fixed order (gain -> filter -> distance model) to
     * each member. The order matches a sequence of the three single-source
     * calls, so the resulting per-source state is identical to applying them
     * one source at a time.
     *
     * Every member is always processed and the first AL error is left pending
     * for the caller, exactly like the equivalent single-source sequence.
     * Returns the number of members processed.
     */
    auto setGainFilterDistance(ALfloat gain, ALuint filter, ALenum model) const -> std::size_t
    {
        /* No alGetError calls inside the loop: OpenAL keeps the first error
         * pending until the caller queries it, and polling here would swallow
         * the very error a sequence of single-source calls would have kept.
         * Every member still receives every applicable call, so the resulting
         * per-source state is identical to running the three setters one
         * source at a time.
         */
        std::size_t processed{0};
        for(ALuint source : mSources)
        {
            alSourcef(source, AL_GAIN, gain);
            alSourcei(source, AL_DIRECT_FILTER, static_cast<ALint>(filter));
            alSourcei(source, AL_DISTANCE_MODEL, static_cast<ALint>(model));
            ++processed;
        }
        return processed;
    }

private:
    std::vector<ALuint> mSources;
};

} // namespace altest

#endif // AL_TESTS_SOURCE_GROUP_H
